<?php
namespace qqworld_collector\module\collect_item; use qqworld_collector\lib; class comment_content extends lib { var $guid; public function init() { add_filter( 'qqworld-collector-collecting-engine-collect-item-' . $this->guid, array($this, 'filter'), 10, 7 ); add_filter( 'qqworld-collector-collecting-engine-collect-item-after-filter-' . $this->guid, array($this, 'filter_after'), 10, 6 ); } public function filter($items, $args, $source_link, $html, $download_args, $settings, $mode) { $lazyload = isset($args['lazyload']) ? $args['lazyload'] : ''; $wipe = isset($args['wipe']) ? $args['wipe'] : array(); $wipe_script = isset($wipe['script']) ? filter_var($wipe['script'], FILTER_VALIDATE_BOOLEAN) : 1; $wipe_style = isset($wipe['style']) ? filter_var($wipe['style'], FILTER_VALIDATE_BOOLEAN) : 1; $wipe_tag_comment = isset($wipe['tag-comment']) ? filter_var($wipe['tag-comment'], FILTER_VALIDATE_BOOLEAN) : 1; $wipe_empty_tags = isset($wipe['empty-tags']) ? filter_var($wipe['empty-tags'], FILTER_VALIDATE_BOOLEAN) : 1; $wipe_links = isset($wipe['links']) ? filter_var($wipe['links'], FILTER_VALIDATE_BOOLEAN) : 1; $patterns = array(); $replacements = array(); if ( apply_filters('qqworld-collector-wipe-script-from-post-content', $wipe_script) ) { $patterns[] = '/<script[^>]*?>[\s\S]*?<\/script>/i'; $replacements[] = ''; } if ( apply_filters('qqworld-collector-wipe-style-from-post-content', $wipe_style) ) { $patterns[] = '/ style="[^"]*?"/i'; $replacements[] = ''; $patterns[] = '/ style=\'[^\']*?\'/i'; $replacements[] = ''; $patterns[] = '/<style[^>]*?>[\s\S]*?<\/style>/i'; $replacements[] = ''; } if ( apply_filters('qqworld-collector-wipe-empty-tags-from-post-content', $wipe_empty_tags) ) $items = $this->wipe_empty_tags($items); if ( apply_filters('qqworld-collector-wipe-links-from-post-content', $wipe_links) ) { $patterns[] = '/<a.*?>|<\/a>/i'; $replacements[] = ''; } if (!empty($patterns)) $items = preg_replace($patterns, $replacements, $items); if ( apply_filters('qqworld-collector-wipe-tag-comment-from-post-content', $wipe_tag_comment) ) { $items = preg_replace_callback('/<!--([\s\S]*?)-->/i', function($matches) { return $matches[1] == 'nextpage' ? $matches[0] : ''; }, $items); } if ($lazyload) { $pattern = $this->encode_pattern($lazyload); $preg = preg_match_all('/<img[\s\S]*?>/i', $items[0], $matches); if ($preg) { foreach ($matches[0] as $match) { if (preg_match('/ '.$pattern.'="/i', $match)) { $replacement = preg_replace('/ src="[\s\S]*?"/i', '', $match); $replacement = preg_replace('/ '.$pattern.'="/i', ' src="', $replacement); $items[0] = str_replace($match, $replacement, $items[0]); } } } } return $items; } public function filter_after($items, $args, $source_link, $html, $settings, $mode) { if (!empty($items)) { $strip_tags = isset($args['strip-tags']) ? $args['strip-tags'] : 1; if ($strip_tags) $items = strip_tags($items); } return $items; } } ?>